CREATE TABLE IF NOT EXISTS articles (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, excerpt TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '[]', cover_url TEXT NOT NULL DEFAULT '', cover_alt TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', published_at TEXT, meta_title TEXT NOT NULL DEFAULT '', meta_description TEXT NOT NULL DEFAULT '', author TEXT NOT NULL DEFAULT '', author_account_id TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE INDEX IF NOT EXISTS idx_articles_status_published ON articles (status, published_at DESC); CREATE INDEX IF NOT EXISTS idx_articles_category_published ON articles (category, status, published_at DESC);
